SourceCode.Declaration:
/// <summary>
/// The <c>AVAWHSControlCreateLicensePlateId</c> class is responsible for handling the license plate id controls on the mobile device.
/// </summary>
#AVAWHSRF
[
    WhsControlFactory(#AVALicensePlateId)
]
public class AVAWHSControlCreateLicensePlateId extends WhsControl
{
}

Method.Source:
public boolean process()
{
    boolean         valid;
    WHSLicensePlate licensePlate;

    valid = super();

    if (valid
     && pass.lookupStr(ProcessGuideDataTypeNames::AVASuccessMsg))
    {
        valid = true;
    }
    else if (this.parmData())
    {
        licensePlate = WHSLicensePlate::find(this.parmData());

        if (licensePlate)
        {
            this.fail(strFmt("@NDX:AVALicencePlateExists", this.parmData()));
        }
        else
        {
            fieldValues.insert(#AVALicensePlateId, this.parmData());
        }
    }
    else
    {
        this.fail("@NDX:AVALicencePlateMissing");
    }

    return valid;
}

public boolean canProcessDefaultValue()
{
    if (this.parmData())
    {
        return true;
    }

    return false;
}
